file.specification:

// NEW ACTIONS to add to existing action union:
// APPLY_CHAIN_ENERGY: { chainLength: number; usedWild: boolean }
// ROUND_END: { reason: 'SHORT_CHAIN' | 'FARKLE' | 'ENERGY_ZERO' }
// LOG_DECISION: { decision: DecisionContext }  -- passed to analytics, no state change
// WILD_SCATTER: {} -- triggers when 3+ wilds on board simultaneously
// ARCHIVIST_RECOVER: {} -- 15% of farkle pool recovered per chain (Rally only)

// ROUND FLOW (replace old match flow):
//   Chain len 6 → score > 0 → CONTINUE (multiplier advances, stay ROLLING)
//   Chain len 2-5 → score > 0 → AUTO-BANK → ROUND_END reason: SHORT_CHAIN
//   Any chain → score = 0 → ROUND_END reason: FARKLE (no bank, points lost)
//   Energy = 0 callback → AUTO-BANK → ROUND_END reason: ENERGY_ZERO
//
// AUTO-BANK: unbanked transfers to banked, multiplier resets to step 0.
// FARKLE: unbanked resets to 0, multiplier resets to step 0.
//         In Rally/Heist: lost unbanked → farklePool (not discarded).

// COMMIT_CHAIN case additions:
//   After scoreFarkle(): dispatch LOG_DECISION with full DecisionContext
//   Check result.isSixOfAKind → place BOMB_STANDARD cell at chain center
//   Check result.isStraight → place BOMB_RAINBOW cell at chain center
//   Check resolveWilds() if any chain cell has state === 'WILD'
//   After scoring: check scanForWilds(grid) >= 3 → dispatch WILD_SCATTER

// SpawnPool: SixPoolManager instance in useRef (not in state).
//   Created once on mount: new SixPoolManager(gridSize, csprng)
//   spawnTiles() calls pool.draw() for each empty cell
//   Dead board check: if (!hasValidChain(grid)) → pool reshuffle then respawn

// CASCADE: setTimeout recursion at CASCADE_MS (80ms). NEVER setInterval.
//   Step 1: stepGravity()
//   Step 2: spawnTiles() using SixPoolManager
//   Step 3: normalizeTiles()
//   Step 4: when stable → check dead board → REFILL_COMPLETE

// CHAIN_MIN enforcement: chain.length < 2 → do not dispatch COMMIT_CHAIN.
//   This gate is in useGame only — scoreFarkle() has no minimum.

// Skill logging:
//   On every COMMIT_CHAIN: collect DecisionContext and call analytics.insertChainDecision()
//   Fire-and-forget. Never await. Wrapped in try/catch.
//   On session end / ROUND_END: call analytics.insertSession() with full SessionAnalytics.
